CREATE TABLE IF NOT EXISTS gis_phase326_normalized_geometries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_feature_id uuid NOT NULL REFERENCES gis_spatial_features(id) ON DELETE CASCADE,provider text NOT NULL,dataset_id uuid,geometry_json jsonb NOT NULL,original_geometry_hash text,geometry_valid boolean NOT NULL,corrections jsonb NOT NULL DEFAULT '[]'::jsonb,validation_issues jsonb NOT NULL DEFAULT '[]'::jsonb,crs text NOT NULL DEFAULT 'EPSG:4326',algorithm_version text NOT NULL DEFAULT 'phase326-v1',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_feature_id,algorithm_version));